<?php
namespace App\Controllers\Customer;
use App\Core\Controller; use App\Helpers\CustomerAuth;
class Configurator extends Controller {
  public function quote(): void { $this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$u=$this->customer();$b=$this->getBody();$productId=(int)($b['product_id']??0);$qty=max(1,min(100,(int)($b['quantity']??1)));$product=$this->db()->query("SELECT id,name,base_price FROM vp_products WHERE id=? AND status='published' LIMIT 1",[$productId])->row_array();if(!$product)$this->error('Product not found',404);$selected=array_values(array_unique(array_map('intval',$b['option_value_ids']??[])));$groups=$this->db()->query('SELECT id,name,is_required FROM vp_product_option_groups WHERE product_id=? ORDER BY sort_order,id',[$productId])->result_array()?:[];$selections=[];$price=(float)$product['base_price'];foreach($groups as $group){$values=$this->db()->query('SELECT id,name,price_delta FROM vp_product_option_values WHERE option_group_id=? AND is_active=1',[(int)$group['id']])->result_array()?:[];$chosen=array_values(array_filter($values,fn($v)=>in_array((int)$v['id'],$selected,true)));if((int)$group['is_required']===1&&count($chosen)!==1)$this->error('Choose one option for '.$group['name'],422);foreach($chosen as $value){$price+=(float)$value['price_delta'];$selections[]=['groupId'=>(int)$group['id'],'group'=>$group['name'],'valueId'=>(int)$value['id'],'value'=>$value['name'],'priceDelta'=>(float)$value['price_delta']];}}$this->success(['productId'=>$productId,'productName'=>$product['name'],'quantity'=>$qty,'unitPrice'=>$price,'totalPrice'=>$price*$qty,'selections'=>$selections],'Configuration quoted'); }
  public function upload(): void { $this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$u=$this->customer();if(empty($_FILES['file'])||!is_array($_FILES['file']))$this->error('File is required',422);$f=$_FILES['file'];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)$this->error('Upload failed',422);$max=(int)(\Env::CUSTOMER_UPLOAD_MAX_BYTES??52428800);if((int)$f['size']<1||(int)$f['size']>$max)$this->error('File size is invalid',422);$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf','application/zip'=>'zip'];if(!isset($allowed[$mime]))$this->error('Allowed files: JPG, PNG, PDF, ZIP',422);$productId=(int)($_POST['product_id']??0);if($productId>0&&!$this->db()->query('SELECT id FROM vp_products WHERE id=? LIMIT 1',[$productId])->row_array())$this->error('Product not found',404);$key='customer-uploads/'.(int)$u['id'].'/'.date('Y/m').'/'.bin2hex(random_bytes(16)).'.'.$allowed[$mime];$root=defined('Env::MEDIA_STORAGE_PATH')&&\Env::MEDIA_STORAGE_PATH!==''?rtrim(\Env::MEDIA_STORAGE_PATH,'/\\'):dirname(__DIR__,4).'/public/uploads';$target=$root.'/'.$key;if(!is_dir(dirname($target))&&!mkdir(dirname($target),0750,true))$this->error('Upload storage unavailable',500);if(!move_uploaded_file($f['tmp_name'],$target))$this->error('Failed to store upload',500);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$id=$this->db()->insert('vp_design_uploads',['customer_id'=>(int)$u['id'],'product_id'=>$productId?:null,'original_name'=>substr(basename((string)$f['name']),0,255),'storage_key'=>$key,'mime_type'=>$mime,'size_bytes'=>(int)$f['size'],'created_at'=>$now]);$this->success(['id'=>(int)$id,'name'=>basename((string)$f['name']),'mimeType'=>$mime,'sizeBytes'=>(int)$f['size'],'url'=>rtrim((string)(\Env::MEDIA_BASE_URL??''),'/').'/uploads/'.$key],'File uploaded'); }
  private function customer(): array {$u=CustomerAuth::user();if(!$u)$this->error('Unauthorized',401);return $u;}
}
